import { itemsLits } from "items";
import { cloneObj } from "utils";
import { GameScene } from "../modules";

export class TestLocation extends GameScene {
  constructor() {
    super(
      {
        // image: ["tiles", "assets/locations/Objects.png"],
        // tilemapTiledJSON: ["locationMap", "assets/locations/cloud_city.json"],
        spritesheet: [
          [
            "characters",
            "assets/locations/characters.png",
            { frameWidth: 52, frameHeight: 72 },
          ],
        ],
      },
      "assets/locations/cloud_city.json",
      {
        boxes: [
          {
            lock: 0,
            items: [
              //@ts-ignore
              { ...cloneObj(itemsLits.other[0]), amount: 5000 },
              //@ts-ignore
              { ...cloneObj(itemsLits.other[1]), amount: 966074 },
            ],
          },
          {
            lock: 15,
            items: [
              //@ts-ignore
              { ...cloneObj(itemsLits.other[1]), amount: 966074 },
              cloneObj(itemsLits.saturator[0]),
              cloneObj(itemsLits.saturator[0]),
              cloneObj(itemsLits.saturator[0]),
              cloneObj(itemsLits.saturator[0]),
              cloneObj(itemsLits.saturator[0]),
              cloneObj(itemsLits.saturator[0]),
            ],
          },
        ],
        characters: {
          player: {
            sprite: "characters",
            startedPosition: { x: 25, y: 20 },
            scale: 0.8,
            id: "Player",
            type: "human",
          },
          enemy: {
            Monster: {
              id: "Monster",
              scale: 1.25,
              sprite: "characters",
              startedPosition: { x: 27, y: 37 },
              type: "monster",
            },
          },
          NPC: {},
        },
        // lights: [{ x: 9, y: 13, positionType: "tile" }],
        flames: [{ x: 10, y: 14, positionType: "tile", radius: 8, zIndex: Infinity,  }],
      },
    );
  }

  update(time: number, delta: number) {
    super.update(time, delta);
  }
}
